using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Threading;using System.Windows.Media;using System.Windows.Media.Imaging;
namespace Iris {
    public static class DiscordCachedIcons {
        static readonly Regex iconKey=new Regex(@"https://cdn\.discordapp\.com/icons/(?<id>[0-9]{1,20})/[a-zA-Z0-9_]+\.(?:webp|png|jpe?g|gif)(?:\?[^\s\x00]*)?",RegexOptions.Compiled);
        static byte[] Slice(string file,long position,int count){if(count<1||count>17*1024*1024||position<0)return null;try{using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){if(position>input.Length-count)return null;input.Position=position;var bytes=new byte[count];int done=0,read;while(done<count&&(read=input.Read(bytes,done,count-done))>0)done+=read;return done==count?bytes:null;}}catch{return null;}}
        static byte[] Body(string directory,uint address,int count){if(count<1||count>2*1024*1024||(address&0x80000000)==0)return null;int type=(int)((address>>28)&7);if(type==0)return Slice(Path.Combine(directory,"f_"+(address&0x0fffffff).ToString("x6")),0,count);if(type<2||type>4||(address&0x0c000000)!=0)return null;int block=type==2?256:type==3?1024:4096;int capacity=block*((int)((address>>24)&3)+1);if(count>capacity)return null;return Slice(Path.Combine(directory,"data_"+((address>>16)&255)),8192L+(address&65535)*block,count);}
        public static ImageSource Decode(byte[] bytes){if(bytes==null)return null;try{using(var input=new MemoryStream(bytes,false)){var decoder=BitmapDecoder.Create(input,BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnDemand);var frame=decoder.Frames[0];if(frame.PixelWidth<1||frame.PixelHeight<1||frame.PixelWidth>2048||frame.PixelHeight>2048)return null;input.Position=0;var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.DecodePixelWidth=Math.Min(64,frame.PixelWidth);image.StreamSource=input;image.EndInit();image.Freeze();return image;}}catch{return null;}}
        public static Dictionary<string,ImageSource> Read(IEnumerable<string> ids,CancellationToken token){string appData=Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);return Read(ids,new[]{"discord","discordptb","discordcanary"}.Select(name=>Path.Combine(appData,name,"Cache","Cache_Data")),token);}
        public static Dictionary<string,ImageSource> Read(IEnumerable<string> ids,IEnumerable<string> directories,CancellationToken token){var wanted=new HashSet<string>(ids.Where(id=>Regex.IsMatch(id??"",@"^[0-9]{1,20}$")));var result=new Dictionary<string,ImageSource>();if(wanted.Count==0)return result;var stop=DateTime.UtcNow.AddSeconds(2);foreach(string directory in directories){token.ThrowIfCancellationRequested();string entries=Path.Combine(directory,"data_1");byte[] data;try{var info=new FileInfo(entries);if(!info.Exists||info.Length<8192||info.Length>17*1024*1024)continue;data=Slice(entries,0,(int)info.Length);}catch{continue;}if(data==null||BitConverter.ToUInt32(data,0)!=0xc104cac3||BitConverter.ToInt32(data,12)!=256)continue;
                for(int offset=8192;offset+256<=data.Length;offset+=256){if((offset&32767)==0){token.ThrowIfCancellationRequested();if(DateTime.UtcNow>stop)return result;}int keyLength=BitConverter.ToInt32(data,offset+32),state=BitConverter.ToInt32(data,offset+20);uint longKey=BitConverter.ToUInt32(data,offset+36);if(state!=0||longKey!=0||keyLength<30||keyLength>927||offset+96+keyLength>data.Length)continue;string key=Encoding.UTF8.GetString(data,offset+96,keyLength);var match=iconKey.Match(key);if(!match.Success)continue;string id=match.Groups["id"].Value;if(!wanted.Contains(id)||result.ContainsKey(id))continue;int length=BitConverter.ToInt32(data,offset+44);var body=Body(directory,BitConverter.ToUInt32(data,offset+60),length);var image=Decode(body);if(image==null)continue;var check=Slice(entries,offset,256);if(check==null||!check.SequenceEqual(data.Skip(offset).Take(256)))continue;result[id]=image;if(result.Count==wanted.Count)return result;}
            }return result;}
        public static void SavePng(string path,ImageSource image){var bitmap=image as BitmapSource;if(bitmap==null)return;Directory.CreateDirectory(Path.GetDirectoryName(path));var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));string temp=path+".tmp";using(var file=File.Create(temp))png.Save(file);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
    }
}
